}

import type { SessionUser } from "@fantappero/contracts";

const ACCESS_TOKEN_KEY = "fantappero.accessToken";
const REFRESH_TOKEN_KEY = "fantappero.refreshToken";
const USER_KEY = "fantappero.sessionUser";

export type StoredSession = {
  accessToken: string;
  refreshToken: string;
  user: SessionUser;
};

export function loadStoredSession(): StoredSession | null {
  if (typeof sessionStorage === "undefined") {
    return null;
  }
  const accessToken = sessionStorage.getItem(ACCESS_TOKEN_KEY);
  const refreshToken = sessionStorage.getItem(REFRESH_TOKEN_KEY);
  const userRaw = sessionStorage.getItem(USER_KEY);
  if (!accessToken || !refreshToken || !userRaw) {
    return null;
  }
  try {
    return {
      accessToken,
      refreshToken,
      user: JSON.parse(userRaw) as SessionUser,
    };
  } catch {
    clearStoredSession();
    return null;
  }
}

export function saveStoredSession(session: StoredSession): void {
  sessionStorage.setItem(ACCESS_TOKEN_KEY, session.accessToken);
  sessionStorage.setItem(REFRESH_TOKEN_KEY, session.refreshToken);
  sessionStorage.setItem(USER_KEY, JSON.stringify(session.user));
}

export function clearStoredSession(): void {
  sessionStorage.removeItem(ACCESS_TOKEN_KEY);
  sessionStorage.removeItem(REFRESH_TOKEN_KEY);
  sessionStorage.removeItem(USER_KEY);
}

import type { SessionUser } from "@fantappero/contracts";

const ACCESS_TOKEN_KEY = "fantappero.accessToken";
const REFRESH_TOKEN_KEY = "fantappero.refreshToken";
const USER_KEY = "fantappero.sessionUser";
const ACTIVE_LEAGUE_ID_KEY = "fantappero.activeLeagueId";

export type StoredSession = {
  accessToken: string;
  refreshToken: string;
  user: SessionUser;
};

export function loadStoredSession(): StoredSession | null {
  if (typeof sessionStorage === "undefined") {
    return null;
  }
  const accessToken = sessionStorage.getItem(ACCESS_TOKEN_KEY);
  const refreshToken = sessionStorage.getItem(REFRESH_TOKEN_KEY);
  const userRaw = sessionStorage.getItem(USER_KEY);
  if (!accessToken || !refreshToken || !userRaw) {
    return null;
  }
  try {
    return {
      accessToken,
      refreshToken,
      user: JSON.parse(userRaw) as SessionUser,
    };
  } catch {
    clearStoredSession();
    return null;
  }
}

export function saveStoredSession(session: StoredSession): void {
  sessionStorage.setItem(ACCESS_TOKEN_KEY, session.accessToken);
  sessionStorage.setItem(REFRESH_TOKEN_KEY, session.refreshToken);
  sessionStorage.setItem(USER_KEY, JSON.stringify(session.user));
}

export function clearStoredSession(): void {
  sessionStorage.removeItem(ACCESS_TOKEN_KEY);
  sessionStorage.removeItem(REFRESH_TOKEN_KEY);
  sessionStorage.removeItem(USER_KEY);
  sessionStorage.removeItem(ACTIVE_LEAGUE_ID_KEY);
}

export function loadStoredActiveLeagueId(): string | null {
  if (typeof sessionStorage === "undefined") {
    return null;
  }
  return sessionStorage.getItem(ACTIVE_LEAGUE_ID_KEY);
}

export function saveStoredActiveLeagueId(leagueId: string): void {
  sessionStorage.setItem(ACTIVE_LEAGUE_ID_KEY, leagueId);
}

export function clearStoredActiveLeagueId(): void {
  sessionStorage.removeItem(ACTIVE_LEAGUE_ID_KEY);
}

import {
  AppHeader,
  AppShell,
  BottomNav,
  BrandLogo,
  LeagueSelector,
  SidebarNav,
} from "@fantappero/ui";
import { type ReactNode } from "react";
import { Link, useLocation } from "../router/simpleRouter";
import { useAuth } from "../auth/AuthContext";
import { LogoutButton } from "../auth/LogoutButton";
import { ADMIN_NAV_ITEMS, APP_NAV_ITEMS, filterNavItems } from "../navigation/navConfig";
import {
  IconCart,
  IconLayout,
  IconShield,
  IconTrophy,
  IconUser,
  IconUsers,
} from "../navigation/NavIcons";
import { RouterBottomNavLink, RouterNavLinkAdapter } from "../navigation/RouterNavLink";
import { SkipLink } from "./SkipLink";

const APP_ICONS: Record<string, ReactNode> = {
  leagues: <IconTrophy />,
  matchday: <IconLayout />,
  standings: <IconTrophy />,
  roster: <IconUsers />,
  formation: <IconLayout />,
  auction: <IconCart />,
  market: <IconCart />,
  "league-admin": <IconShield />,
  profile: <IconUser />,
};

function NavIcon({ id }: { id: string }) {
  return APP_ICONS[id] ?? null;
}

export function AppLayout({ children }: { children: React.ReactNode }) {
  const { user, leagues, activeLeagueId, setActiveLeagueId, can } = useAuth();
  const location = useLocation();
  const navItems = filterNavItems(APP_NAV_ITEMS, can, location.pathname).map((item) => ({
    id: item.id,
    label: item.label,
    href: item.path,
    active: item.active,
    icon: <NavIcon id={item.id} />,
  }));

  const showLeagueSelector = leagues.length > 0 && location.pathname !== "/leghe";

  return (
    <AppShell
      surface="app"
      className="fa-surface-pitch fa-surface-pitch--subtle"
      skipLink={<SkipLink />}
      header={
        <AppHeader
          brand={
            <Link to="/leghe" aria-label="FantApperò, home">
              <BrandLogo variant="full" size="sm" />
            </Link>
          }
          contextSlot={
            showLeagueSelector ? (
              <LeagueSelector
                label="Lega attiva"
                leagues={leagues.map((league) => ({
                  value: league.id,
                  label: league.name,
                }))}
                value={activeLeagueId ?? leagues[0]?.id ?? ""}
                onChange={setActiveLeagueId}
                placeholder="Seleziona lega"
              />
            ) : null
          }
          actionsSlot={
            <>
              {can(["global:operate"]) ? (
                <Link to="/admin" className="fa-link-muted" data-testid="admin-panel-link">
                  Pannello globale
                </Link>
              ) : null}
              <span className="fa-user-chip" data-testid="user-display">
                {user.displayName}
              </span>
              <LogoutButton />
            </>
          }
        />
      }
      sidebar={
        <SidebarNav
          items={navItems}
          linkComponent={RouterNavLinkAdapter}
          ariaLabel="Navigazione lega"
        />
      }
      bottomNav={
        <BottomNav
          items={navItems}
          linkComponent={RouterBottomNavLink}
          ariaLabel="Navigazione mobile lega"
        />
      }
    >
      {children}
    </AppShell>
  );
}

export function AdminLayout({ children }: { children: React.ReactNode }) {
  const { user, can } = useAuth();
  const location = useLocation();
  const navItems = filterNavItems(ADMIN_NAV_ITEMS, can, location.pathname).map((item) => ({
