"""Validation rules for league creation (EP03-01)."""

from __future__ import annotations

from datetime import UTC, datetime
from uuid import UUID

from auth.exceptions import ValidationAuthError

_LEAGUE_NAME_MAX_LENGTH = 120
_MIN_COMPETITIONS = 3
_SEASON_YEAR_MIN = 2020


def validate_league_name(name: str) -> str:
    cleaned = name.strip()
    if not cleaned:
        raise ValidationAuthError("Inserisci un nome per la lega.", code="invalid_league_name")
    if len(cleaned) > _LEAGUE_NAME_MAX_LENGTH:
        raise ValidationAuthError(
            "Il nome della lega è troppo lungo.",
            code="invalid_league_name",
        )
    return cleaned


def validate_season_year(season_year: int) -> int:
    max_year = datetime.now(UTC).year + 1
    if season_year < _SEASON_YEAR_MIN or season_year > max_year:
        raise ValidationAuthError(
            "Seleziona una stagione valida.",
            code="invalid_season_year",
        )
    return season_year


def validate_competition_ids(competition_ids: list[UUID]) -> list[UUID]:
    if len(competition_ids) != len(set(competition_ids)):
        raise ValidationAuthError(
            "Seleziona ogni campionato una sola volta.",
            code="duplicate_competitions",
        )
    if len(competition_ids) < _MIN_COMPETITIONS:
        raise ValidationAuthError(
            f"Seleziona almeno {_MIN_COMPETITIONS} campionati.",
            code="insufficient_competitions",
        )
    return competition_ids

"""Validation rules for league creation and regulation configuration."""

from __future__ import annotations

from datetime import UTC, datetime
from uuid import UUID

from auth.exceptions import ValidationAuthError

_LEAGUE_NAME_MAX_LENGTH = 120
_MIN_COMPETITIONS = 3
_SEASON_YEAR_MIN = 2020
STANDARD_PRESET_NAME = "standard"
MIN_PARTICIPANTS = 4
MAX_PARTICIPANTS = 10
STANDARD_PARTICIPANT_COUNT = 8
STANDARD_ROSTER_SIZE = 35
STANDARD_GOALKEEPERS = 3
STANDARD_DEFENDERS = 11
STANDARD_MIDFIELDERS = 11
STANDARD_FORWARDS = 10
STANDARD_TOTAL_CREDITS = 1000


def validate_league_name(name: str) -> str:
    cleaned = name.strip()
    if not cleaned:
        raise ValidationAuthError("Inserisci un nome per la lega.", code="invalid_league_name")
    if len(cleaned) > _LEAGUE_NAME_MAX_LENGTH:
        raise ValidationAuthError(
            "Il nome della lega è troppo lungo.",
            code="invalid_league_name",
        )
    return cleaned


def validate_season_year(season_year: int) -> int:
    max_year = datetime.now(UTC).year + 1
    if season_year < _SEASON_YEAR_MIN or season_year > max_year:
        raise ValidationAuthError(
            "Seleziona una stagione valida.",
            code="invalid_season_year",
        )
    return season_year


def validate_competition_ids(competition_ids: list[UUID]) -> list[UUID]:
    if len(competition_ids) != len(set(competition_ids)):
        raise ValidationAuthError(
            "Seleziona ogni campionato una sola volta.",
            code="duplicate_competitions",
        )
    if len(competition_ids) < _MIN_COMPETITIONS:
        raise ValidationAuthError(
            f"Seleziona almeno {_MIN_COMPETITIONS} campionati.",
            code="insufficient_competitions",
        )
    return competition_ids


def validate_preset_name(preset_name: str) -> str:
    cleaned = preset_name.strip().lower()
    if cleaned != STANDARD_PRESET_NAME:
        raise ValidationAuthError(
            "È disponibile solo il preset Standard.",
            code="invalid_rules_preset",
        )
    return cleaned


def validate_participant_count(participant_count: int) -> int:
    if participant_count < MIN_PARTICIPANTS or participant_count > MAX_PARTICIPANTS:
        raise ValidationAuthError(
            f"Il numero partecipanti deve essere tra {MIN_PARTICIPANTS} e {MAX_PARTICIPANTS}.",
            code="invalid_participant_count",
        )
    return participant_count


def validate_total_credits(total_credits: int) -> int:
    if total_credits <= 0:
        raise ValidationAuthError(
            "I crediti devono essere maggiori di zero.",
            code="invalid_total_credits",
        )
    return total_credits


def validate_standard_roster(
    *,
    roster_size: int,
    goalkeepers: int,
    defenders: int,
    midfielders: int,
    forwards: int,
) -> None:
    if roster_size != STANDARD_ROSTER_SIZE:
        raise ValidationAuthError(
            f"La rosa deve contenere esattamente {STANDARD_ROSTER_SIZE} giocatori.",
            code="invalid_roster_size",
        )
    if (
        goalkeepers != STANDARD_GOALKEEPERS
        or defenders != STANDARD_DEFENDERS
        or midfielders != STANDARD_MIDFIELDERS
        or forwards != STANDARD_FORWARDS
    ):
        raise ValidationAuthError(
            "La composizione rosa deve essere 3P-11D-11C-10A.",
            code="invalid_roster_distribution",
        )
    if goalkeepers + defenders + midfielders + forwards != roster_size:
        raise ValidationAuthError(
            "La somma dei ruoli deve coincidere con la dimensione della rosa.",
            code="invalid_roster_distribution",
        )

"""League validation unit tests (EP03-01)."""
from __future__ import annotations
from uuid import UUID
import pytest
from auth.exceptions import ValidationAuthError from leagues.validators import validate_competition_ids, validate_league_name, validate_season_year
def test_validate_league_name_trims() -> None: assert validate_league_name(" Lega Test ") == "Lega Test"
def test_validate_league_name_rejects_empty() -> None: with pytest.raises(ValidationAuthError, match="nome per la lega"): validate_league_name(" ")
def test_validate_season_year_accepts_current_window() -> None: assert validate_season_year(2026) == 2026
def test_validate_season_year_rejects_out_of_range() -> None: with pytest.raises(ValidationAuthError, match="stagione valida"): validate_season_year(2010)
def test_validate_competition_ids_requires_minimum() -> None: ids = [ UUID("00000000-0000-4000-8000-000000000001"), UUID("00000000-0000-4000-8000-000000000002"), ] with pytest.raises(ValidationAuthError, match="almeno 3"): validate_competition_ids(ids)
def test_validate_competition_ids_rejects_duplicates() -> None: duplicate = UUID("00000000-0000-4000-8000-000000000001") ids = [duplicate, duplicate, UUID("00000000-0000-4000-8000-000000000002")] with pytest.raises(ValidationAuthError, match="una sola volta"): validate_competition_ids(ids)
def test_validate_competition_ids_accepts_three_unique() -> None: ids = [ UUID("00000000-0000-4000-8000-000000000001"), UUID("00000000-0000-4000-8000-000000000002"), UUID("00000000-0000-4000-8000-000000000003"), ] assert validate_competition_ids(ids) == ids

"""League validation unit tests (EP03-01)."""
from __future__ import annotations
from uuid import UUID
import pytest
from auth.exceptions import ValidationAuthError from leagues.validators import ( validate_competition_ids, validate_league_name, validate_participant_count, validate_preset_name, validate_season_year, validate_standard_roster, validate_total_credits, )
def test_validate_league_name_trims() -> None: assert validate_league_name(" Lega Test ") == "Lega Test"
def test_validate_league_name_rejects_empty() -> None: with pytest.raises(ValidationAuthError, match="nome per la lega"): validate_league_name(" ")
def test_validate_season_year_accepts_current_window() -> None: assert validate_season_year(2026) == 2026
def test_validate_season_year_rejects_out_of_range() -> None: with pytest.raises(ValidationAuthError, match="stagione valida"): validate_season_year(2010)
def test_validate_competition_ids_requires_minimum() -> None: ids = [ UUID("00000000-0000-4000-8000-000000000001"), UUID("00000000-0000-4000-8000-000000000002"), ] with pytest.raises(ValidationAuthError, match="almeno 3"): validate_competition_ids(ids)
def test_validate_competition_ids_rejects_duplicates() -> None: duplicate = UUID("00000000-0000-4000-8000-000000000001") ids = [duplicate, duplicate, UUID("00000000-0000-4000-8000-000000000002")] with pytest.raises(ValidationAuthError, match="una sola volta"): validate_competition_ids(ids)
def test_validate_competition_ids_accepts_three_unique() -> None: ids = [ UUID("00000000-0000-4000-8000-000000000001"), UUID("00000000-0000-4000-8000-000000000002"), UUID("00000000-0000-4000-8000-000000000003"), ] assert validate_competition_ids(ids) == ids
def test_validate_preset_name_accepts_standard() -> None: assert validate_preset_name("Standard") == "standard"
def test_validate_preset_name_rejects_unknown() -> None: with pytest.raises(ValidationAuthError, match="solo il preset Standard"): validate_preset_name("custom")
def test_validate_participant_count_rejects_outside_range() -> None: with pytest.raises(ValidationAuthError, match="tra 4 e 10"): validate_participant_count(3)
def test_validate_total_credits_requires_positive() -> None: with pytest.raises(ValidationAuthError, match="maggiori di zero"): validate_total_credits(0)
def test_validate_standard_roster_rejects_wrong_distribution() -> None: with pytest.raises(ValidationAuthError, match="3P-11D-11C-10A"): validate_standard_roster( roster_size=35, goalkeepers=4, defenders=10, midfielders=11, forwards=10, )

