/** League configuration contracts (EP03-01). */

/** Competition available in the MVP catalog. */
export interface CompetitionSummary {
  id: string;
  providerId: number;
  name: string;
  country: string;
}

/** Detailed league view including selected competitions. */
export interface LeagueDetail {
  id: string;
  name: string;
  seasonYear: number;
  state: "draft" | "active";
  viewerRole: "member" | "league_admin" | null;
  competitions: CompetitionSummary[];
}

export interface CreateLeagueRequest {
  name: string;
  seasonYear: number;
  competitionIds: string[];
}

/** League configuration contracts (EP03-02). */

/** Competition available in the MVP catalog. */
export interface CompetitionSummary {
  id: string;
  providerId: number;
  name: string;
  country: string;
}

export interface LeagueRosterConfig {
  rosterSize: number;
  goalkeepers: number;
  defenders: number;
  midfielders: number;
  forwards: number;
}

export interface LeagueRulesOptions {
  allowTrades: boolean;
  allowManualInvites: boolean;
}

export interface LeagueRules {
  presetName: "standard";
  participantCount: number;
  participantMin: number;
  participantMax: number;
  roster: LeagueRosterConfig;
  totalCredits: number;
  options: LeagueRulesOptions;
}

/** Detailed league view including selected competitions. */
export interface LeagueDetail {
  id: string;
  name: string;
  seasonYear: number;
  state: "draft" | "active";
  viewerRole: "member" | "league_admin" | null;
