  name: string;
  seasonYear: number;
  competitionIds: string[];
}

export interface UpdateLeagueRulesRequest {
  presetName: "standard";
  participantCount: number;
  roster: LeagueRosterConfig;
  totalCredits: number;
  options: LeagueRulesOptions;
}

export interface LeagueAdminPanel {
  leagueId: string;
  message: string;
  rules: LeagueRules;
}
